mapper.select:
SELECT STATUS AS status, TRADE_CODE AS tradeCode, PROD_ID AS prodId, ASSET_CODE AS assetCode, CCY AS ccy, AMT AS amt, num AS num, ASSET_METHOD AS assetMethod, CUR_ASSET_TYPE AS curAssetType, CUR_ASSETDET_TYPE AS curAssetdetType, DEALDATE AS dealdate, TRADE_COUNTER AS tradeCounter, RIVAL_PARTY_TYPE AS rivalPartyType, UNIT_PRICE_FULL AS unitPriceFull, UNIT_PRICE_NET AS unitPriceNet, END_RATE AS endRate, CONTRACT_CODE AS contractCode, REMARK AS remark, CREATE_USER AS createUser, CREATE_TIME AS createTime, UPDATE_USER AS updateUser, UPDATE_TIME AS updateTime, DATA_SOURCE AS dataSource, '' AS DATAUUID FROM chb_invest_trade a
NOT EXISTS ( SELECT 1 FROM chb_invest_trade_errordata WHERE TRADE_CODE = a.TRADE_CODE AND STATUS IN ( 'A', 'E' ) ) UNION ALL
#{pId,jdbcType=VARCHAR}
#{ac,jdbcType=VARCHAR}
and a.TRADE_CODE like concat('%', #{tradeCode},'%')
and a.DEALDATE >= #{dealdateStart}
and a.DEALDATE <= #{dealdateEnd}
#{status,jdbcType=VARCHAR}
SELECT 'A' AS status, TRADE_CODE AS tradeCode, PROD_ID AS prodId, ASSET_CODE AS assetCode, NULL AS ccy, NULL AS amt, NULL AS num, NULL AS assetMethod, NULL AS curAssetType, NULL AS curAssetdetType, NULL AS dealdate, NULL AS tradeCounter, NULL AS rivalPartyType, NULL AS unitPriceFull, NULL AS unitPriceNet, NULL AS endRate, NULL AS contractCode, NULL AS remark, CREATE_USER AS createUser, CREATE_TIME AS createTime, UPDATE_USER AS updateUser, UPDATE_TIME AS updateTime, 'DB' AS dataSource, DATAUUID AS DATAUUID FROM chb_invest_trade_errordata i
STATUS IN ( 'A', 'E' )
#{pId,jdbcType=VARCHAR}
#{ac,jdbcType=VARCHAR}
and i.TRADE_CODE like concat('%', #{tradeCode},'%')
and i.DEALDATE >= #{dealdateStart}
and i.DEALDATE <= #{dealdateEnd}
#{status,jdbcType=VARCHAR}

